function yxSaveConditions(i,j){if(!yxIsHuman())return toast('配置只读');const yxR=yxRule(i,j),yxFields=[...document.querySelectorAll('[data-yx-field]:checked')].map(yxE=>yxE.dataset.yxField),yxEvidence=[...document.querySelectorAll('[data-yx-evidence]:checked')].map(yxE=>yxE.dataset.yxEvidence);if(['缺陷','线上故障'].includes(yxState.type)){const yxFloor=yxStates()[j][1]===3?['每条验收标准都有通过的证据','内部验收通过']:j===3?['关联 MR 已合入']:j===4?['部署制品包含合入提交']:j===5?['必需自动验证全部通过']:j===6?['内部验收通过']:[];if(yxFloor.some(yxE=>!yxEvidence.includes(yxE)))return toast('缺陷证据下限不可移除','triangle-alert');if(j===7&&(!yxFields.includes('解决结果')||!yxFields.includes('引入阶段')||!document.getElementById('yxAgentNo').checked||yxVal('yxRole')!=='测试角色'||yxVal('yxWiRole')!=='负责人'))return toast('关闭需解决结果、引入阶段及人类验证角色','triangle-alert');if([8,9].includes(j)&&!document.getElementById('yxAgentNo').checked)return toast('产品取舍仅人类；重复缺陷例外需关联原缺陷','triangle-alert');if([5,6].includes(j)&&document.getElementById('yxManual').checked)return toast('内部验证推进由系统执行','triangle-alert');if(j===4&&!yxFields.includes('修复版本'))return toast('已部署必须填写修复版本','triangle-alert');}Object.assign(yxR,{fields:yxFields,evidence:yxEvidence,user:yxVal('yxUser'),role:yxVal('yxRole'),wiRole:yxVal('yxWiRole'),agentNo:document.getElementById('yxAgentNo').checked,relation:yxVal('yxRelation'),manual:document.getElementById('yxManual').checked});yxState.dirty=true;toast('条件已保存在本地草稿；请预览影响后保存配置');}
