function yxCheckConnection(){if(!yxIsHuman())return toast('仅人类集成管理员可检测连接');if(!yxState.connected)return toast('连接已停用');if(yxState.preview==='异常'){yxState.checked=false;return toast('模拟检测失败：401；同步暂停','triangle-alert');}yxState.checked=true;route();toast('模拟检测通过；未发起真实云效请求');}
function yxTokenModal(){yxModal('更新云效连接',`${yxField('组织 ID','yxOrg','org-northwind-001')}${yxField('个人访问令牌（只写）','yxToken','','password')}<div class="note danger">更新令牌影响同步访问。需重新认证；原型不保存令牌明文、不调用云效。</div><label class="row"><input id="yxTokenConfirm" type="checkbox">你已完成重新认证（仅演示）</label>`,'yxTokenSave()','确认更新',true);}
function yxTokenSave(){if(!yxIsHuman())return yxError('仅人类集成管理员可更新连接');if(!yxVal('yxOrg')||!yxVal('yxToken')||!document.getElementById('yxTokenConfirm').checked)return yxError('请填写组织和令牌并确认重新认证演示');document.getElementById('yxToken').value='';yxState.connected=true;yxState.checked=false;yxState.preview='正常';closeModal();route();toast('演示连接已更新，请重新检测；令牌未保存');}
