function yxParseCSV(text){const yxRows=[];let yxRow=[],yxCell='',yxQuoted=false;for(let yxI=0;yxI<text.length;yxI++){const yxC=text[yxI];if(yxC==='"'){if(yxQuoted&&text[yxI+1]==='"'){yxCell+='"';yxI++;}else yxQuoted=!yxQuoted;}else if(yxC===','&&!yxQuoted){yxRow.push(yxCell);yxCell='';}else if((yxC==='\n'||yxC==='\r')&&!yxQuoted){if(yxC==='\r'&&text[yxI+1]==='\n')yxI++;yxRow.push(yxCell);if(yxRow.some(yxV=>yxV.trim()))yxRows.push(yxRow);yxRow=[];yxCell='';}else yxCell+=yxC;}if(yxQuoted)throw new Error('CSV 引号未闭合');if(yxCell||yxRow.length){yxRow.push(yxCell);yxRows.push(yxRow);}return yxRows;}
async function yxReadCSV(file){if(!file)return;if(file.size>2*1024*1024)return toast('请使用不超过 2 MB 的 CSV');try{const yxRows=yxParseCSV((await file.text()).replace(/^\uFEFF/,''));if(yxRows[0]&&yxRows[0][0]==='标题')yxRows.shift();if(yxRows.length>500)return toast('每次最多导入 500 行');if(yxRows.some(yxR=>yxR.length!==6||!yxR[0]||!yxR[3]||!yxR[4]||!/^P[0-5]$/.test(yxR[5]||'P2')))return toast('CSV 列数或必填字段不符；等级须为 P0–P5','triangle-alert');yxState.csv=yxRows;route();toast('已读取 CSV，尚未导入');}catch(yxErr){toast('无法读取 CSV：'+yxEsc(yxErr.message),'triangle-alert');}}
function yxImportCSV(){if(!yxIsHuman())return toast('仅人类集成管理员可导入');if(!yxState.csv.length)return;yxState.csv.forEach(yxR=>yxState.cases.push({p:'p1',id:'TC-CSV-'+(yxState.cases.length+1),ac:yxAC.some(yxA=>yxA[0]===yxR[1])?yxR[1]:'未归类',title:yxR[0],pre:yxR[2],step:yxR[3],expected:yxR[4],priority:yxR[5]||'P2',result:'未执行',actor:'chen',evidence:'',note:'Testhub CSV 导入；未归类用例不计覆盖率'}));yxState.csv=[];route();toast('用例已导入本地样例；未归类项不计覆盖率');}
